+// API keys, roles and the audit trail (docs/DATA.md). Keys live in `apiKeys`
+// as { key, name, role }; audit entries in `audit`, oldest first.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** The roles a key may have, from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// What a cook may do besides reading. Managers may do everything.
+const COOK_ACTIONS = new Set(["cook", "waste", "temperature", "count"]);
+
+const digest = (text) => createHash("sha256").update(String(text)).digest();
+
+/** The key record for a bearer token, or null when the token is missing or unknown. */
+export function findKey(store, token) {
+  if (typeof token !== "string" || token === "") return null;
+  const wanted = digest(token);
+  let found = null;
+  for (const k of store.data.apiKeys) if (timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  return found;
+}
+
+/** Whether `role` may do `action`: read, cook, waste, temperature, count, audit or manage. */
+export function can(role, action) {
+  if (role === "manager") return true;
+  if (role !== "viewer" && role !== "cook") return false;
+  if (action === "read") return true;
+  return role === "cook" && COOK_ACTIONS.has(action);
+}
+
+/** Appends an audit entry { id, at, keyName, method, path, status }. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
