+// Which action each route needs (see `can` in src/domain/access.js) and
+// reading the bearer token from a request.
+
+// Routes that need something other than the default: GET routes are "read",
+// every other route is "manage".
+const ACTIONS = {
+  "POST /recipes/:id/cook": "cook",
+  "POST /batches/:id/waste": "waste",
+  "POST /temperatures": "temperature",
+  "POST /stocktakes/:id/counts": "count",
+  "GET /audit": "audit",
+};
+
+/** The action a route (method and pattern) needs. */
+export function actionFor(method, pattern) {
+  return ACTIONS[`${method} ${pattern}`] ?? (method === "GET" ? "read" : "manage");
+}
+
+/** The token from an `Authorization: Bearer <key>` header, or null. */
+export function bearerToken(headers) {
+  const header = headers.authorization ?? headers.Authorization;
+  const m = typeof header === "string" ? /^Bearer\s+(\S+)\s*$/i.exec(header) : null;
+  return m ? m[1] : null;
+}
