+++ b/tests/auth.test.js
@@ -0,0 +1,57 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("a missing or unknown key is 401 in the error shape", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  const notBearer = await raw({ path: "/items", headers: { authorization: "larder-manager-e41c6b07" } });
+  assert.equal(notBearer.status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { raw, store } = app();
+  assert.equal((await raw({ path: "/items", headers: auth("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await raw({ method: "POST", path: "/recipes/1/cook", headers: auth("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { raw, store } = app();
+  const cook = (method, path, body) => raw({ method, path, body, headers: auth("cook") });
+  assert.equal((await cook("POST", "/recipes/1/cook", { portions: 1 })).status, 200);
+  assert.equal((await cook("POST", "/batches/6/waste", { qty: 0.5, reason: "spill" })).status, 201);
+  assert.equal((await cook("POST", "/temperatures", { location: "fridge", celsius: 3 })).status, 201);
+  const take = await raw({ method: "POST", path: "/stocktakes", headers: auth("manager"), body: { location: "dry" } });
+  assert.equal((await cook("POST", `/stocktakes/${take.body.id}/counts`, { batchId: 6, counted: 12 })).status, 200);
+  assert.equal((await cook("POST", "/stocktakes", { location: "fridge" })).status, 403);
+  assert.equal((await cook("POST", `/stocktakes/${take.body.id}/finish`)).status, 403);
+  assert.equal((await cook("POST", "/orders", { supplierId: 1, lines: [{ itemId: 4, qty: 1 }] })).status, 403);
+  assert.equal((await cook("PUT", "/items/1/allergens", { allergens: [] })).status, 403);
+  assert.equal(store.data.orders.length, 3);
+});
+
+test("changes are audited; GET /audit is for managers, newest first", async () => {
+  const { raw, store } = app();
+  await raw({ path: "/items", headers: auth("cook") });
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/jobs/nightly", headers: auth("cook") });
+  await raw({ method: "POST", path: "/jobs/nightly", headers: { authorization: "Bearer nope" } });
+  assert.equal(store.data.audit.length, 2);
+  assert.equal((await raw({ path: "/audit", headers: auth("cook") })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: auth("viewer") })).status, 403);
+  const res = await raw({ path: "/audit", headers: auth("manager") });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })), [
+    { keyName: "Line cook", method: "POST", path: "/jobs/nightly", status: 403 },
+    { keyName: "Line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+});
